-- WBG tracker: starting data for the Business support tab (HR support log, 24 requests).
-- Run AFTER upgrade-4-v3-stage1.sql. TEST PROJECT first. Re-runnable (existing rows are kept).
begin;
select setval('public.support_ref_seq', greatest((select coalesce(max(substring(ref from 4)::int),0) from public.support_requests where ref ~ '^SR-[0-9]+$'), 1));
commit;
